import Foundation

/// Loads the bundled emoji database generated by `scripts/gen-emoji.mjs`.
public struct EmojiStore: Sendable {
    public let emoji: [Emoji]
    public let source: String
    private let byName: [String: Emoji]

    public init(emoji: [Emoji], source: String = "inline") {
        self.emoji = emoji
        self.source = source
        var map: [String: Emoji] = [:]
        for e in emoji { for n in e.names where map[n] == nil { map[n] = e } }
        self.byName = map
    }

    private struct File: Decodable {
        struct Entry: Decodable { let e: String; let n: [String]; let k: [String]?; let s: [String]?; let o: Int? }
        let source: String
        let emoji: [Entry]
    }

    public init(jsonData: Data) throws {
        let file = try JSONDecoder().decode(File.self, from: jsonData)
        self.init(emoji: file.emoji.map { Emoji(emoji: $0.e, names: $0.n, keywords: $0.k ?? [], skins: $0.s, order: $0.o ?? 0) },
                  source: file.source)
    }

    /// The emoji database bundled in this package's resources.
    public static func bundled() throws -> EmojiStore {
        guard let url = Bundle.module.url(forResource: "emoji", withExtension: "json") else {
            throw CocoaError(.fileNoSuchFile)
        }
        return try EmojiStore(jsonData: Data(contentsOf: url))
    }

    public func emoji(named name: String) -> Emoji? { byName[name.lowercased()] }
}
